#!/usr/bin/env node
// Feature 029: collect every *placed* Gemini Notebook Studio artifact into static/studio-index.json,
// which the topic page's Studio panel fetches at runtime (same convention as content-index.json:
// generated by prestart/prebuild, gitignored, not a source of truth).
//
// Shape: { "<course>/<unit>/<topic>": { "en": [item...], "ur": [item...] }, "teasers": { "<COURSE-CODE>": teaser } }
// item = { kind, part?, title, audience, alt, src?, url? }   (src = site path of a text asset)
// teaser = { youtube_id, title, locale, semester, published_at, views }: Feature 030 (T038), only teasers
// the owner made public; views from specs/studio/teaser-stats.json (teaser-stats.mjs).
// homeTeasers = [{ code, ...teaser, reason: 'top' | 'latest' }]: the home page's "Courses in 30 seconds".
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { findManifests } from './check-studio-manifest.mjs';
import { renderDeck, validateOutline } from './studio-slides.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');

export function buildStudioIndex(manifests) {
  const index = {};
  for (const m of manifests) {
    for (const a of m.artifacts) {
      if (a.status !== 'placed') continue;
      const key = `${m.course}/${m.unit}/${a.topic}`;
      const slot = (index[key] ??= { en: [], ur: [] });
      slot[a.locale].push({
        kind: a.kind,
        ...(a.part ? { part: a.part } : {}),
        title: a.title,
        audience: a.audience ?? 'all',
        alt: a.alt ?? '',
        ...(a.asset_path ? { src: a.asset_path } : {}),
        ...(a.host_url ? { url: a.host_url } : {}),
      });
    }
  }
  for (const slot of Object.values(index)) {
    for (const loc of ['en', 'ur']) slot[loc].sort((x, y) => x.kind.localeCompare(y.kind) || (x.part ?? 0) - (y.part ?? 0));
  }
  return index;
}

/**
 * Public course teasers by course code, from the teaser ledger (specs/studio/teasers/media-teasers.json).
 * Only state `public`: an uploaded-private, checked or owner-approved Short is still private on
 * YouTube and must never appear on the site. Urdu is preferred (teasers are Urdu-first, D-2026-0083).
 */
export function buildTeaserIndex(ledger, loadScript, stats = {}) {
  const out = {};
  for (const i of ledger?.items ?? []) {
    if (i.state !== 'public' || !/^[A-Za-z0-9_-]{11}$/.test(i.youtube_id ?? '')) continue;
    const script = loadScript(i.id);
    if (!script?.course_code) continue; // the licence teaser has no course card or overview
    if (out[script.course_code] && out[script.course_code].locale === 'ur' && i.locale !== 'ur') continue;
    out[script.course_code] = {
      youtube_id: i.youtube_id,
      title: script.locales?.[i.locale]?.youtube_title ?? script.title?.[i.locale] ?? script.course_code,
      locale: i.locale,
      semester: script.semester ?? null,
      published_at: i.published_at ?? null,
      views: stats.videos?.[i.youtube_id]?.views ?? 0,
    };
  }
  return out;
}

/**
 * The home page's four teasers (owner, 2026-11-22): the `top` most watched, then the `latest`
 * newest by published_at that are not already picked. Ties in views go to the newer one. Only
 * teasers with an overview route (a semester) qualify.
 */
export function pickHomeTeasers(teasers, { top = 2, latest = 2 } = {}) {
  const all = Object.entries(teasers).filter(([, t]) => t.semester).map(([code, t]) => ({ code, ...t }));
  const newer = (a, b) => (b.published_at ?? '').localeCompare(a.published_at ?? '') || a.code.localeCompare(b.code);
  const picked = [...all].filter((t) => t.views > 0).sort((a, b) => b.views - a.views || newer(a, b)).slice(0, top).map((t) => ({ ...t, reason: 'top' }));
  const taken = new Set(picked.map((t) => t.code));
  const fresh = [...all].filter((t) => !taken.has(t.code)).sort(newer).slice(0, latest + (top - picked.length)).map((t) => ({ ...t, reason: 'latest' }));
  return [...picked, ...fresh];
}

/**
 * Feature 032: public animated figures (specs/studio/animations/placed.json) as `animation` items
 * of the topic that holds the figure, so the Studio panel can list them. Only public 16:9 videos.
 * `topicOf(course, unit, figId)` returns the topic number; `titleOf(course, figId, lang)` a title.
 */
export function addAnimations(index, ledger, topicOf, titleOf) {
  for (const a of ledger?.animations ?? []) {
    if (a.status !== 'public' || a.format !== '16x9' || !/^[A-Za-z0-9_-]{11}$/.test(a.youtube_id ?? '')) continue;
    const m = a.figure.match(/^\/img\/figures\/([a-z0-9-]+)\/unit-(\d+)\/(fig-[A-Za-z0-9-]+)$/);
    if (!m) continue;
    const [, course, unitStr, figId] = m;
    const unit = Number(unitStr);
    const topic = topicOf(course, unit, figId);
    if (!topic) continue;
    const slot = (index[`${course}/${unit}/${topic}`] ??= { en: [], ur: [] });
    slot[a.lang].push({ kind: 'animation', title: titleOf(course, figId, a.lang) ?? figId, audience: 'all', alt: '', url: `https://youtu.be/${a.youtube_id}` });
  }
  return index;
}

/**
 * Feature 032 phase C: flashcards from the reviewed bilingual glossary (glossary.json). For each
 * topic, the glossary terms that occur in its English text are ranked by how specific they are to
 * it (occurrences here x rarity across all topics) and the top `max` kept. Pure.
 * topics: [{ key: 'course/unit/topic', text }]; glossary: [{ term, definition_en, definition_ur }];
 * urTerms: Map(lowercase EN term -> UR term) from specs/content/terminology.csv.
 */
export function buildFlashcards(topics, glossary, urTerms = new Map(), { max = 10, min = 4, origin = {} } = {}) {
  const esc = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const entries = glossary.filter((e) => e.term && e.definition_en && e.definition_ur)
    .map((e) => ({ e, re: new RegExp(`(^|[^A-Za-z])${esc(e.term)}(s|es)?(?![A-Za-z])`, 'gi') }));
  const hits = topics.map((t) => entries.map(({ e, re }) => [e, (t.text.match(re) || []).length]).filter(([, n]) => n > 0));
  const df = new Map();
  for (const h of hits) for (const [e] of h) df.set(e.term, (df.get(e.term) ?? 0) + 1);
  const N = topics.length;
  const out = {};
  topics.forEach((t, i) => {
    const course = t.key.split('/')[0].toUpperCase();
    const ranked = hits[i]
      .filter(([e]) => (df.get(e.term) ?? 0) <= Math.max(3, N * 0.3)) // drop terms nearly every topic uses
      // A term from this topic's own course; another course's term only if the topic leans on it.
      // Another course's term only if it is a multi-word term the topic leans on ("a fraction of a
      // second" must not make "Fraction" a card in a memory topic).
      .filter(([e, n]) => (origin[e.term] ? origin[e.term] === course : n >= 2) || (n >= 3 && /\s/.test(e.term)))
      .map(([e, n]) => [e, n, origin[e.term] === course])
      .map(([e, n, own]) => [e, n * Math.log(N / (df.get(e.term) ?? 1)) * (own ? 2 : 1)])
      .sort((a, b) => b[1] - a[1] || a[0].term.localeCompare(b[0].term))
      .slice(0, max).map(([e]) => e);
    if (ranked.length < min) return;
    out[t.key] = {
      en: ranked.map((e) => ({ term: e.term, definition: e.definition_en })),
      ur: ranked.map((e) => ({ term: urTerms.get(e.term.toLowerCase()) ?? e.term, definition: e.definition_ur })),
    };
  });
  return out;
}

/** Problems with an authored topic deck. Pure. */
export function validateDeck(d) {
  const errs = [];
  for (const loc of ['en', 'ur']) {
    const cards = d?.[loc];
    if (!Array.isArray(cards) || cards.length < 4 || cards.length > 12) { errs.push(`${loc}: 4 to 12 cards`); continue; }
    cards.forEach((c, i) => {
      if (!c?.term?.trim() || !c?.definition?.trim()) errs.push(`${loc} card ${i + 1}: term and definition`);
      if (/[\u2014\u2015\u2E3A\u2E3B]/.test(`${c?.term}${c?.definition}`)) errs.push(`${loc} card ${i + 1}: long dash`);
      if ((c?.definition ?? '').length > 300) errs.push(`${loc} card ${i + 1}: definition over 300 characters`);
    });
  }
  if (Array.isArray(d?.en) && Array.isArray(d?.ur) && d.en.length !== d.ur.length) errs.push('en and ur card counts differ');
  return errs;
}

/** Write one deck file per unit (static/studio/flashcards/<course>/unit-NN.json) and index each topic. */
function readFlashcards(root, index) {
  const glossaryFile = join(root, 'glossary.json');
  if (!existsSync(glossaryFile)) return index;
  const urTerms = new Map();
  const csv = join(root, 'specs', 'content', 'terminology.csv');
  if (existsSync(csv)) for (const line of readFileSync(csv, 'utf8').trim().split('\n').slice(1)) {
    const [en, ur] = line.split(',').map((x) => x.replace(/^"|"$/g, '').trim());
    if (en && ur) urTerms.set(en.toLowerCase(), ur);
  }
  const topics = [];
  for (const sem of readdirSync(join(root, 'docs')).filter((d) => d.startsWith('semester-'))) {
    for (const course of readdirSync(join(root, 'docs', sem))) {
      const cdir = join(root, 'docs', sem, course);
      if (!statSync(cdir).isDirectory() || !readdirSync(cdir).some((u) => /^unit-\d+$/.test(u))) continue;
      for (const unit of readdirSync(cdir).filter((u) => /^unit-\d+$/.test(u))) {
        for (const f of readdirSync(join(cdir, unit)).filter((n) => /^topic-\d+\.mdx$/.test(n))) {
          topics.push({ key: `${course}/${Number(unit.slice(5))}/${Number(f.match(/\d+/)[0])}`, text: readFileSync(join(cdir, unit, f), 'utf8') });
        }
      }
    }
  }
  const originFile = join(root, 'specs', 'studio', 'glossary-origin.json');
  const origin = existsSync(originFile) ? JSON.parse(readFileSync(originFile, 'utf8')) : {};
  const decks = buildFlashcards(topics, JSON.parse(readFileSync(glossaryFile, 'utf8')), urTerms, { origin });
  // Authored decks (crew `flashcards` stage) live in specs/studio/flashcards/<course>/unit-NN.json,
  // outside every review manifest; an authored topic deck replaces the glossary-derived one.
  const authoredDir = join(root, 'specs', 'studio', 'flashcards');
  if (existsSync(authoredDir)) for (const course of readdirSync(authoredDir).filter((c) => /^[a-z]{4}-\d{3}$/.test(c))) {
    for (const f of readdirSync(join(authoredDir, course)).filter((n) => /^unit-\d{2}\.json$/.test(n))) {
      const unit = Number(f.slice(5, 7));
      const deck = JSON.parse(readFileSync(join(authoredDir, course, f), 'utf8'));
      for (const [topic, d] of Object.entries(deck.topics ?? {})) {
        const errs = validateDeck(d);
        if (errs.length) { console.warn(`build-studio-index: skipped ${course} unit ${unit} topic ${topic}: ${errs.join('; ')}`); continue; }
        decks[`${course}/${unit}/${topic}`] = d;
      }
    }
  }
  if (process.argv.includes('--coverage')) {
    const covered = new Set(Object.keys(decks).map((k) => k.split('/').slice(0, 2).join('/')));
    const units = [...new Set(topics.map((t) => t.key.split('/').slice(0, 2).join('/')))];
    const needed = units.filter((u) => !covered.has(u)).sort();
    writeFileSync(join(root, 'specs', 'studio', 'flashcards-needed.json'), `${JSON.stringify({ note: 'Units with no flashcard deck: the crew flashcards stage authors specs/studio/flashcards/<course>/unit-NN.json for them. Regenerate: node scripts/build-studio-index.mjs --coverage', units: needed }, null, 1)}\n`);
    console.log(`flashcards: ${units.length - needed.length} unit(s) covered, ${needed.length} need an authored deck`);
  }
  const byUnit = new Map();
  for (const [key, deck] of Object.entries(decks)) {
    const [course, unit, topic] = key.split('/');
    const k = `${course}/${unit}`;
    byUnit.set(k, { ...(byUnit.get(k) ?? {}), [topic]: deck });
  }
  for (const [k, deck] of byUnit) {
    const [course, unit] = k.split('/');
    const rel = `studio/flashcards/${course}/unit-${String(unit).padStart(2, '0')}.json`;
    mkdirSync(join(root, 'static', 'studio', 'flashcards', course), { recursive: true });
    writeFileSync(join(root, 'static', rel), `${JSON.stringify(deck)}\n`);
    for (const topic of Object.keys(deck)) {
      const slot = (index[`${course}/${unit}/${topic}`] ??= { en: [], ur: [] });
      for (const loc of ['en', 'ur']) slot[loc].push({ kind: 'flashcards', title: '', audience: 'all', alt: '', src: `/${rel}#${topic}` });
    }
  }
  return index;
}

/**
 * Feature 032 phase B: web slide decks from specs/studio/slides/<course>/unit-NN.json, written to
 * static/studio/slides/<course>/unit-NN.<lang>.html and listed on every topic of the unit. The
 * PowerPoint beside each deck (unit-NN.<lang>.pptx) is built offline (scripts/studio/slides-pptx.py).
 */
function readSlides(root, index) {
  const dir = join(root, 'specs', 'studio', 'slides');
  if (!existsSync(dir)) return index;
  for (const course of readdirSync(dir).filter((c) => /^[a-z]{4}-\d{3}$/.test(c))) {
    for (const f of readdirSync(join(dir, course)).filter((n) => /^unit-\d{2}\.json$/.test(n))) {
      const outline = JSON.parse(readFileSync(join(dir, course, f), 'utf8'));
      const errs = validateOutline(outline);
      if (errs.length) { console.warn(`build-studio-index: skipped slides ${course}/${f}: ${errs.slice(0, 3).join('; ')}`); continue; }
      const unit = Number(f.slice(5, 7));
      mkdirSync(join(root, 'static', 'studio', 'slides', course), { recursive: true });
      const sem = readdirSync(join(root, 'docs')).find((d) => d.startsWith('semester-') && existsSync(join(root, 'docs', d, course, `unit-${f.slice(5, 7)}`)));
      const topics = sem ? readdirSync(join(root, 'docs', sem, course, `unit-${f.slice(5, 7)}`)).filter((n) => /^topic-\d+\.mdx$/.test(n)).map((n) => Number(n.match(/\d+/)[0])) : [];
      for (const lang of ['en', 'ur']) {
        const base = `studio/slides/${course}/unit-${f.slice(5, 7)}.${lang}`;
        writeFileSync(join(root, 'static', `${base}.html`), renderDeck(outline, lang));
        const pptx = existsSync(join(root, 'static', `${base}.pptx`)) ? `/${base}.pptx` : undefined;
        for (const topic of topics) {
          const slot = (index[`${course}/${unit}/${topic}`] ??= { en: [], ur: [] });
          slot[lang].push({ kind: 'deck', title: outline.title[lang], audience: 'all', alt: '', src: `/${base}.html`, ...(pptx ? { url: pptx } : {}) });
        }
      }
    }
  }
  return index;
}

function readAnimations(root, index) {
  const ledger = join(root, 'specs', 'studio', 'animations', 'placed.json');
  if (!existsSync(ledger)) return index;
  const unitDir = (course, unit) => {
    const sem = readdirSync(join(root, 'docs')).find((d) => d.startsWith('semester-') && existsSync(join(root, 'docs', d, course, `unit-${String(unit).padStart(2, '0')}`)));
    return sem ? join(root, 'docs', sem, course, `unit-${String(unit).padStart(2, '0')}`) : null;
  };
  const topicOf = (course, unit, figId) => {
    const dir = unitDir(course, unit);
    if (!dir) return null;
    const f = readdirSync(dir).find((n) => /^topic-\d+\.mdx$/.test(n) && readFileSync(join(dir, n), 'utf8').includes(`id="${figId}"`));
    return f ? Number(f.match(/\d+/)[0]) : null;
  };
  const titleOf = (course, figId, lang) => {
    const f = join(root, 'specs', 'studio', 'animations', course, `${figId}.json`);
    return existsSync(f) ? JSON.parse(readFileSync(f, 'utf8')).beats?.[0]?.caption?.[lang] ?? null : null;
  };
  return addAnimations(index, JSON.parse(readFileSync(ledger, 'utf8')), topicOf, titleOf);
}

function readTeasers(root) {
  const dir = join(root, 'specs', 'studio', 'teasers');
  const ledger = join(dir, 'media-teasers.json');
  if (!existsSync(ledger)) return {};
  const statsFile = join(root, 'specs', 'studio', 'teaser-stats.json'); // beside, not inside, teasers/ (every JSON there is a script)
  const stats = existsSync(statsFile) ? JSON.parse(readFileSync(statsFile, 'utf8')) : {};
  return buildTeaserIndex(JSON.parse(readFileSync(ledger, 'utf8')), (id) => {
    const f = join(dir, `${id}.json`);
    return existsSync(f) ? JSON.parse(readFileSync(f, 'utf8')) : null;
  }, stats);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const manifests = findManifests(ROOT).map((f) => JSON.parse(readFileSync(f, 'utf8')));
  const index = readSlides(ROOT, readFlashcards(ROOT, readAnimations(ROOT, buildStudioIndex(manifests))));
  index.teasers = readTeasers(ROOT);
  index.homeTeasers = pickHomeTeasers(index.teasers);
  mkdirSync(join(ROOT, 'static'), { recursive: true });
  writeFileSync(join(ROOT, 'static', 'studio-index.json'), `${JSON.stringify(index)}\n`);
  console.log(`build-studio-index: ${Object.keys(index).length - 2} topic(s) with placed Studio items, ${Object.keys(index.teasers).length} public teaser(s), home: ${index.homeTeasers.map((t) => `${t.code} (${t.reason})`).join(', ') || 'none'}`);
}
